  "assistant.helper": { en: "FinSakhi uses your financial overview to personalise this conversation, while keeping your details private.", te: "FinSakhi మీ ఆర్థిక అవలోకనాన్ని ఉపయోగించి ఈ సంభాషణను వ్యక్తిగతీకరిస్తుంది, మీ వివరాలను గోప్యంగా ఉంచుతుంది.", hi: "FinSakhi आपके वित्तीय अवलोकन का उपयोग करके इस बातचीत को व्यक्तिगत बनाता है, जबकि आपकी जानकारी सुरक्षित रखता है।" },
  "assistant.tryAsking": { en: "Try asking", te: "అడగడానికి ప్రయత్నించండి", hi: "पूछने का प्रयास करें" },
  "assistant.opening": { en: "Opening FinSakhi AI...", te: "FinSakhi AIని తెరవడం...", hi: "FinSakhi AI खोल रहा है..." },
