  "assistant.voiceUnavailable": { en: "Voice input isn't available in this browser. You can still type your question.", te: "వాయిస్ ఇన్‌పుట్ ఈ బ్రౌజర్‌లో అందుబాటులో లేదు. మీరు మీ ప్రశ్నను టైప్ చేయవచ్చు.", hi: "इस ब्राउज़र में वॉइस इनपुट उपलब्ध नहीं है। आप अभी भी सवाल टाइप कर सकते हैं।" },
  "assistant.voiceFailed": { en: "Could not hear anything. Please try again or type your question.", te: "ఏదీ వినిపలేదు. దయచేసి మళ్లీ ప్రయత్నించండి లేదా మీ ప్రశ్నను టైప్ చేయండి.", hi: "कुछ भी सुनाई नहीं दिया। कृपया फिर से कोशिश करें या अपना सवाल टाइप करें।" },
  "assistant.defaultError": { en: "Something went wrong. Please try asking again.", te: "ఏదో తప్పు జరిగింది. దయచేసి మళ్లీ అడగండి.", hi: "कुछ गलत हो गया। कृपया फिर से पूछें।" },
  "assistant.placeholder": { en: "Ask FinSakhi anything, {name}...", te: "FinSakhiకి ఏదైనా అడగండి, {name}...", hi: "FinSakhi से कुछ भी पूछें, {name}..." },
  "assistant.voiceToggle": { en: "Speak your question", te: "మీ ప్రశ్నను చెప్పండి", hi: "अपना सवाल बोलें" },
  "assistant.sendQuestion": { en: "Send question", te: "ప్రశ్నను పంపండి", hi: "सवाल भेजें" },
  "assistant.privacyNote": { en: "FinSakhi provides educational and budgeting guidance. It does not provide guaranteed financial returns or replace professional financial advice.", te: "FinSakhi విద్యా మరియు బడ్జెట్ మార్గదర్శనను అందిస్తుంది. ఇది నిర్ధారిత ఆర్థిక దిగుబడిని అందించదు లేదా వృత్తిపరమైన ఆర్థిక సలహాను భర్తీ చేయదు.", hi: "FinSakhi शैक्षिक और बजट मार्गदर्शन देता है। यह निश्चित वित्तीय रिटर्न नहीं देता और पेशेवर वित्तीय सलाह का विकल्प नहीं है।" },

