  "settings.languageHelp": { en: "Choose the language for buttons and menus.", te: "బటన్లు మరియు మెనుయ్‌కు భాషను ఎంచుకోండి.", hi: "बटन और मेनू के लिए भाषा चुनें।" },
  "settings.reminders": { en: "Reminders", te: "రిమైండర్లు", hi: "रिमाइंडर" },
  "settings.budgetAlerts": { en: "Budget alerts", te: "బడ్జెట్ అలర్ట్లు", hi: "बजट अलर्ट" },
  "settings.budgetAlertsDesc": { en: "Tell me when I am spending faster than usual.", te: "సాధారణ కంటే వేగంగా ఖర్చు చేస్తున్నప్పుడు నాకు చెప్పండి.", hi: "मुझे बताएं जब मैं सामान्य से तेज़ी से पैसा खर्च कर रहा हूँ।" },
  "settings.savingsReminders": { en: "Savings reminders", te: "పొదుపు రిమైండర్లు", hi: "बचत रिमाइंडर" },
