  "settings.learningRemindersDesc": { en: "Send me one money topic each week.", te: "ప్రతి వారం ఒక ఆర్థిక అంశాన్ని నాకు పంపండి.", hi: "हर सप्ताह मुझे एक पैसे से जुड़ा विषय भेजें।" },
