  "settings.largerText": { en: "Larger text", te: "పెద్ద అక్షరాలు", hi: "बड़ा टेक्स्ट" },
  "settings.largerTextDesc": { en: "Increase the text size everywhere in the app.", te: "అప్లికేషన్‌లో అన్ని చోట్ల అక్షరాల పరిమాణాన్ని పెంచండి.", hi: "ऐप में पूरे टेक्स्ट का आकार बढ़ाएं।" },
