  "settings.simpleViewDesc": { en: "Hide charts and extra decoration. Show only the numbers and lists.", te: "చార్ట్‌లు మరియు అదనపు అలంకరణను దాచండి. సంఖ్యలు మరియు జాబితాలు మాత్రమే చూపించండి.", hi: "चार्ट और अतिरिक्त सजावट छुपाएं। केवल नंबर और सूची दिखाएं।" },
  "settings.privacyIntroOne": { en: "Your financial information is used to personalise your experience — your dashboard, your goals and the answers from FinSakhi AI.", te: "మీ ఆర్థిక సమాచారం మీ అనుభవాన్ని వ్యక్తిగతీకరించడానికి ఉపయోగించబడుతుంది — మీ డాష్‌బోర్డ్, మీ లక్ష్యాలు మరియు FinSakhi AI జవాబులు.", hi: "आपकी वित्तीय जानकारी आपके अनुभव को व्यक्तिगत बनाने के लिए उपयोग की जाती है — आपका डैशबोर्ड, आपके लक्ष्य और FinSakhi AI के उत्तर।" },
  "settings.privacyIntroTwo": { en: "FinSakhi is not a bank and does not hold or move your money. We never ask for your bank PIN, UPI PIN or OTP. No one from FinSakhi will ever ask for them either.", te: "FinSakhi బ్యాంకు కాదు మరియు మీ డబ్బును నిర్వహించదు లేదా తరలించదు. మేము మీ బ్యాంక్ PIN, UPI PIN లేదా OTP అడగము. FinSakhi నుంచి ఎవరూ కూడా వీటిని అడగరు.", hi: "FinSakhi बैंक नहीं है और आपके पैसे को नहीं रखता या ले जाता है। हम कभी भी आपके बैंक PIN, UPI PIN या OTP नहीं मांगते। FinSakhi से कोई भी इन्हें नहीं पूछेगा।" },
  "settings.privacyIntroThree": { en: "In this demo build, your entries are stored in this browser only.", te: "ఈ డెమో నిర్మాణంలో, మీ నమోద్లు ఈ బ్రౌజర్‌లో మాత్రమే నిల్వ చేయబడతాయి.", hi: "इस डेमो बिल्ड में, आपकी प्रविष्टियाँ केवल इसी ब्राउज़र में संग्रहीत होती हैं।" },
