  "insight.addIncome": { en: "Add your income", te: "మీ ఆదాయాన్ని జోడించండి", hi: "अपनी आय जोड़ें" },
  "insight.addIncomeMessage": { en: "Add your income to receive personalized financial insights.", te: "వ్యక్తిగతీకరించిన ఆర్థిక సూచనలు పొందడానికి మీ ఆదాయాన్ని జోడించండి.", hi: "व्यक्तिगत वित्तीय सुझाव पाने के लिए अपनी आय जोड़ें।" },
  "insight.expensesHigher": { en: "Expenses are higher than income", te: "ఖర్చులు ఆదాయాన్ని మించిపోతున్నాయి", hi: "खर्च आय से अधिक है" },
  "insight.expensesHigherMessage": { en: "Your recorded expenses are higher than your income. Review your largest expenses and look for areas where you can reduce spending.", te: "మీ నమోదు చేసిన ఖర్చులు మీ ఆదాయాన్ని మించిపోతున్నాయి. మీ పెద్ద ఖర్చులను పరిశీలించి, తగ్గించగల ప్రాంతాలను గుర్తించండి.", hi: "आपका दर्ज किया गया खर्च आपकी आय से अधिक है। अपने बड़े खर्चों की समीक्षा करें और उन क्षेत्रों को देखें जहाँ आप खर्च कम कर सकते हैं।" },
  "insight.goodSavingHabit": { en: "Good saving habit", te: "మంచి పొదుపు అలవాటు", hi: "अच्छी बचत आदत" },
