  "assistant.welcome": { en: "Hello! I'm FinSakhi AI.\nI can help you understand your income and expenses, plan your savings, and explain money topics in simple words.\nWhat would you like to know?", te: "నమస్కారం! నేను FinSakhi AI.\nమీ ఆదాయం, ఖర్చులను అర్థం చేసుకోవడానికి, పొదుపు ప్రణాళిక చేయడానికి, డబ్బు విషయాలను సులభంగా వివరించడానికి నేను సహాయం చేస్తాను.\nమీరు ఏమి తెలుసుకోవాలనుకుంటున్నారు?", hi: "नमस्ते! मैं FinSakhi AI हूँ।\nमैं आपकी आय और खर्च समझने, बचत की योजना बनाने और पैसे से जुड़े विषय सरल शब्दों में समझाने में मदद कर सकता हूँ।\nआप क्या जानना चाहते हैं?" },
  "assistant.suggestion1": { en: "I earn ₹15,000. How can I save?", te: "నేను ₹15,000 సంపాదిస్తున్నాను. ఎలా పొదుపు చేయాలి?", hi: "मैं ₹15,000 कमाता हूँ। मैं कैसे बचत करूँ?" },
  "assistant.suggestion2": { en: "What is an emergency fund?", te: "అత్యవసర నిధి అంటే ఏమిటి?", hi: "आपातकालीन फंड क्या है?" },
  "assistant.suggestion3": { en: "How can I reduce my expenses?", te: "నా ఖర్చులను ఎలా తగ్గించాలి?", hi: "मैं अपने खर्च कैसे कम करूँ?" },
  "assistant.suggestion4": { en: "What is a fixed deposit?", te: "ఫిక్స్డ్ డిపాజిట్ అంటే ఏమిటి?", hi: "फिक्स्ड डिपॉज़िट क्या है?" },
