export type TranslationKey = keyof typeof dict;

export function t(key: TranslationKey, lang: Language = "en"): string {
  const entry = dict[key];
  return entry?.[lang] ?? entry?.en ?? key;
}

export function fillTemplate(template: string, values: Record<string, string | number>): string {
  return template.replace(/\{(\w+)\}/g, (_, key: string) => String(values[key] ?? `{${key}}`));
}

export function getLocalizedString(
  value: string | { en: string; te?: string; hi?: string } | undefined,
  lang: Language = "en",
): string {
  if (!value) return "";
  if (typeof value === "string") return value;
  return value[lang] ?? value.en ?? "";
}

export function getLocalizedRemember(
  value: string[] | { en: string[]; te?: string[]; hi?: string[] } | undefined,
  lang: Language = "en",
): string[] {
  if (!value) return [];
  if (Array.isArray(value)) return value;
  return value[lang] ?? value.en ?? [];
}

export function getCategoryLabel(id: string, lang: Language = "en"): string {
  const key = `category.${id}` as TranslationKey;
  return t(key, lang);
}

const DEMO_DISPLAY_KEYS: Record<string, TranslationKey> = {
  "monthly salary": "demo.monthlySalary",
  salary: "demo.salary",
  groceries: "demo.groceries",
  "school fees": "demo.schoolFees",
  "bus travel": "demo.busTravel",
  "bus pass": "demo.busPass",
  "vegetables and milk": "demo.vegetablesMilk",
  medicines: "demo.medicines",
  "gas cylinder": "demo.gasCylinder",
  "auto to market": "demo.autoToMarket",
  "village function gift": "demo.villageFunctionGift",
  "emergency fund": "demo.emergencyFund",
  "child education": "demo.childEducation",
  healthcare: "demo.healthcare",
  "house repair": "demo.houseRepair",
  "small business": "demo.smallBusiness",
  vehicle: "demo.vehicle",
  food: "category.food",
  transport: "category.transport",
  education: "category.education",
  household: "category.household",
  shopping: "category.shopping",
  other: "category.other",
  income: "category.income",
  "Food": "category.food",
  "Transport": "category.transport",
  "Education": "category.education",
  "Healthcare": "category.healthcare",
  "Household": "category.household",
  "Shopping": "category.shopping",
  "Other": "category.other",
  "Income": "category.income",
};

export function getDemoDisplayLabel(value: string, lang: Language = "en"): string {
  const key = DEMO_DISPLAY_KEYS[value.trim().toLowerCase()];
  return key ? t(key, lang) : value;
}

export function getLocalizedDemoText(value: string, lang: Language = "en"): string {
  return Object.keys(DEMO_DISPLAY_KEYS)
    .sort((a, b) => b.length - a.length)
    .reduce((text, entry) => {
      const label = getDemoDisplayLabel(entry, lang);
      const escaped = entry.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
      return text.replace(new RegExp(escaped, "gi"), label);
    }, value);
}
